// Parse COMTRADE response — fix: handle n8n split items
const PARTNERS = {
  0: 'World', 156: 'China', 840: 'USA', 392: 'Japan',
  410: 'Korea', 608: 'Philippines', 360: 'Indonesia',
  458: 'Malaysia', 276: 'Germany', 356: 'India'
};
const COMMODITIES = {
  '1006': 'Rice', '0901': 'Coffee', '0904': 'Pepper',
  '4001': 'Rubber', '0714': 'Cassava'
};

let items = [];
try { items = $('Fetch COMTRADE').all().map(i => i.json); } catch(e) {}

let dataArr = [];
for (const item of items) {
  if (item.data) {
    let inner = typeof item.data === 'string' ? JSON.parse(item.data) : item.data;
    if (Array.isArray(inner)) dataArr.push(...inner);
    else dataArr.push(inner);
  } else {
    dataArr.push(item);
  }
}

const rows = [];
if (dataArr.length > 0) {
  const filtered = dataArr.filter(r => r.motCode === 0 || r.motCode === null);
  const groupMap = {};
  for (const item of filtered) {
    const key = `${item.cmdCode}_${item.partnerCode}`;
    const year = parseInt(item.period);
    if (!groupMap[key] || year > groupMap[key].year) {
      groupMap[key] = {
        year, cmdCode: item.cmdCode, partnerCode: item.partnerCode,
        fobValue: item.fobvalue || item.primaryValue || 0,
        netWgt: item.netWgt || 0
      };
    }
  }
  for (const [key, data] of Object.entries(groupMap)) {
    const commodity = COMMODITIES[data.cmdCode] || data.cmdCode;
    const partner = PARTNERS[data.partnerCode] || `Country_${data.partnerCode}`;
    const valueM = Math.round(data.fobValue / 1000000 * 100) / 100;
    const weightT = Math.round(data.netWgt / 1000);
    rows.push({ source: 'COMTRADE', commodity, metric: `export_value_to_${partner.toLowerCase()}`, value: valueM, unit: 'million_USD', period: String(data.year) });
    if (weightT > 0) {
      rows.push({ source: 'COMTRADE', commodity, metric: `export_volume_to_${partner.toLowerCase()}`, value: weightT, unit: 'tonnes', period: String(data.year) });
    }
  }
}

if (rows.length === 0) {
  return [{ json: { source: 'COMTRADE', commodity: 'Rice', metric: 'no_data', value: 0, unit: 'N/A', period: 'N/A' } }];
}
return rows.map(r => ({ json: r }));
